<?php
/** Publication type and search-route configuration: fixed rendering profiles, safe literal prefixes and explicit CAS, without editing executable manifests. */
declare(strict_types=1);
use function DBLESSCMS\e;
$active=(new \DBLESSCMS\Plugins($context->store))->state('posts')['enabled'];$editing=$id===''?null:($data['types'][$id]??throw new \DBLESSCMS\HttpError(404,'Type unavailable.','posts.error.missing'));
?>
<?php if(!$active): ?><p class="notice"><?= e($t('activationHelp')) ?></p><?php endif; ?>
<section class="panel"><p class="muted"><?= e($t('routeHelp')) ?></p><div class="table-scroll"><table class="extension-table"><caption class="sr-only"><?= e($t('settings')) ?></caption><thead><tr><th><?= e($t('type')) ?></th><th><?= e($t('identifier')) ?></th><th><?= e($t('routeMode')) ?></th><th><?= e($t('actions')) ?></th></tr></thead><tbody>
<?php foreach($data['types'] as $key=>$type):$prefix=\DBLESSCMS\PostTypes::prefix($type); ?><tr><td><?= e(\DBLESSCMS\PostsRouter::label($type,$context->language,true)) ?></td><td><?= e($key) ?></td><td><code><?= e($prefix===null?'/plugins/blog/article?slug={slug}':('/'.($prefix===''?'':$prefix.'/').'{slug}')) ?></code></td><td><div class="row-actions"><?= \DBLESSCMS\AdminTable::action($url('settings',['id'=>$key]),'edit',$t('edit'),$context->base) ?><?php if(!in_array($key,['page','article'],true)): ?><form method="post" action="<?= e($context->url('type-remove')) ?>" data-pages-form data-confirm="<?= e($t('confirm')) ?>"><?php $hidden($key); ?><button class="icon-button" title="<?= e($t('typeRemove')) ?>" aria-label="<?= e($t('typeRemove')) ?>"><?= \DBLESSCMS\Icons::svg('uninstall',$context->base) ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><a class="text-link" href="<?= e($url('settings')) ?>"><?= e($t('typeNew')) ?></a></section>
<div class="posts-library"><form class="panel" method="post" action="<?= e($context->url('type-save')) ?>" data-pages-form><?php $hidden($id); ?><h2><?= e($t($editing===null?'typeNew':'edit')) ?></h2>
<label><?= e($t('identifier')) ?><input name="typeId" maxlength="64" required pattern="[a-z][a-z0-9\-]{0,63}" value="<?= e($id) ?>" <?= $id!==''?'readonly':'' ?>></label>
<?php foreach(['singular','plural'] as $key): ?><label><?= e($t($key)) ?><input name="<?= e($key) ?>" maxlength="100" value="<?= e($editing[$key]??'') ?>" <?= !in_array($id,['page','article'],true)?'required':'' ?>></label><?php endforeach; ?>
<label><?= e($t('kind')) ?><select name="kind" aria-label="<?= e($t('kind')) ?>"><?php foreach(['page','article'] as $kind):if(in_array($id,['page','article'],true)&&$id!==$kind)continue; ?><option value="<?= e($kind) ?>" <?= ($editing['kind']??'page')===$kind?'selected':'' ?>><?= e($t('kind.'.$kind)) ?></option><?php endforeach; ?></select></label>
<label><?= e($t('routeMode')) ?><select name="routeMode" aria-label="<?= e($t('routeMode')) ?>"><?php foreach(['default','root','custom'] as $mode): ?><option value="<?= e($mode) ?>" <?= ($editing['routeMode']??'default')===$mode?'selected':'' ?>><?= e($t('route.'.$mode)) ?></option><?php endforeach; ?></select></label><label><?= e($t('prefix')) ?><input name="prefix" maxlength="128" value="<?= e($editing['prefix']??'') ?>"></label>
<?php foreach(['groups','tags','comments','hierarchical'] as $key): ?><label class="editor-checkbox"><input name="supports_<?= e($key) ?>" type="checkbox" value="1" <?= ($editing[$key]??in_array($key,['groups','tags','hierarchical'],true))?'checked':'' ?>><?= e($t($key==='comments'?'allowComments':$key)) ?></label><?php endforeach; ?><div class="savebar"><button class="button-primary" <?= !$active?'disabled':'' ?>><?= e($t('typeSave')) ?></button></div></form>
<form class="panel" method="post" action="<?= e($context->url('settings')) ?>" data-pages-form><?php $hidden(); ?><label><?= e($t('searchPath')) ?><input name="searchPath" maxlength="128" required value="<?= e($data['searchPath']) ?>"></label><p class="muted"><?= e($t('searchHelp')) ?></p><a class="text-link" href="<?= e($context->base.'/'.$data['searchPath']) ?>" target="_blank" rel="noopener noreferrer"><?= e($t('publicSearch')) ?></a><div class="savebar"><button class="button-primary"><?= e($t('saveSettings')) ?></button></div></form></div>
